<script setup lang="ts">
import type {DirectionAdvice} from '../decision/direction-advisor';
import {dataset} from '../game/tft-data';
defineProps<{advice?:DirectionAdvice;selectedKey?:string|null;selectedDirectionId?:string;budget?:number|null}>();
defineEmits<{selectComp:[key:string,directionId:string];budget:[number|null]}>();
const labels={reroll:'赌狗','four-cost':'84',legendary:'95'};
const name=(id:string)=>dataset.characterById(id)?.display_name??'待更新';
const pct=(p:number)=>p>0&&p<.001?'<0.1%':p>0&&p<.01?(p*100).toFixed(1)+'%':Math.round(p*100)+'%';
</script>
<template><section v-if="advice?.ready" class="directions" data-direction-advisor :data-mode="advice.mode" :aria-busy="!!advice.updating">
  <header><div><span class="eyebrow">{{ advice.round??'对局中' }} · {{ {opening:'开局决策','second-augment':'中期定向','roll-down':'启动与变阵',late:'后期调整'}[advice.milestone] }}</span><h2>{{ advice.message }}</h2></div><span class="direction-mode">{{ advice.updating?'更新中':advice.mode==='selected'?'已选方向':advice.mode==='carry'?'核心已明确':advice.regime?labels[advice.regime]+'方向':'保持摇摆' }}</span></header>
  <nav class="search-budgets" aria-label="搜牌预算"><span>搜牌预算</span><button v-for="amount in [20,40,60,null]" :key="String(amount)" :class="{active:(budget??null)===amount}" :data-search-budget="amount??'wallet'" @click="$emit('budget',amount)">{{ amount===null?'当前金币':amount+' 金' }}</button></nav>
  <div class="direction-cards"><article v-for="row in advice.rows" :key="row.id" :data-suggestion="row.key" :class="{chosen:selectedDirectionId?selectedDirectionId===row.id:selectedKey===row.key}">
    <div class="card-heading"><span>{{ labels[row.regime] }}</span><small>{{ row.labels.join(' · ') }}</small></div>
    <h3>{{ row.name }}</h3>
    <div class="observed-stats" title="MetaTFT 阵容终局聚合统计，API默认窗口；不是当前局面的预计名次。">汇总均名 {{ row.observedPlace.toFixed(2) }} <span>{{ row.observations.toLocaleString() }} 场</span></div>
    <div class="core-pair"><span v-for="id in [row.carry,row.tank]" :key="id" :class="'cost-'+dataset.characterById(id)?.cost"><img :src="dataset.characterById(id)?.image_path" :alt="name(id)"/><b>{{ name(id) }}</b><span class="pair-items"><img v-for="item in row.gearAllocation?.assignments.filter(a=>a.unit===id&&!a.id.includes('Component_'))" :key="item.index" :src="dataset.item(item.id)?.image_path" :alt="dataset.item(item.id)?.display_name??'装备'" :title="(dataset.item(item.id)?.display_name??'装备')+(item.transfer?' · 规划转移给'+name(id):' · '+name(id))"/></span></span><small v-if="row.copies">核心 {{ row.copies }} 张</small></div>
    <div class="route-units"><img v-for="id in row.units" :key="id" :src="dataset.characterById(id)?.image_path" :alt="name(id)" :title="name(id)"/></div>
    <footer><span :title="'按实际出装频率逐件分配给双核；不重复使用物品。转移须处理原持有者，未分配物品可考虑其它英雄。这不是战斗胜率。'">{{ row.gear.supporting.length?'核心装支持':row.tankGear?.supporting.length?'前排装支持':row.gear.known||row.tankGear?.known?'散件方向已比较':'等待装备信号' }}</span><button :data-advisor-pick="row.key" :data-direction-pick="row.id" @click="$emit('selectComp',row.key,row.id)">{{ (selectedDirectionId?selectedDirectionId===row.id:selectedKey===row.key)?'已选用':'选用' }}</button></footer>
  </article></div>
  <div v-if="advice.search?.ready&&!advice.updating" class="search-plan" data-direction-search :data-phase="advice.search.phase">
    <header><strong>{{ advice.mode==='selected'&&advice.regime!=='reroll'?'已选路线 · 双核二星对比':{reroll:'核心追三',flex:'多路线搜牌',upgrade:'核心到手 · 继续追二星',reinforce:'三星已成 · 补强关键牌'}[advice.search.phase] }}</strong><span :title="advice.search.gaps.join('；')">{{ advice.search.level }}级 · {{ advice.search.budget }} 金预算（含买牌）</span></header>
    <div v-if="advice.search.portfolio" class="portfolio"><span>任一路首核补齐</span><b>{{ pct(advice.search.portfolio.completionProbability) }}–{{ pct(advice.search.optimisticProbability??advice.search.portfolio.completionProbability) }}</b><small title="仙灵刷新阶段未同步，分别按四个和五个英雄格参考。">4–5 英雄格</small><div v-if="advice.search.portfolio.buy.length" class="buy-now"><span>当前可留</span><img v-for="id in advice.search.portfolio.buy" :key="id" :src="dataset.characterById(id)?.image_path" :alt="name(id)" :title="name(id)"/></div></div>
    <div v-if="advice.search.keyUpgradePortfolio" class="portfolio" :title="'主C或前排任一升二星，仍不代表战斗已稳定。先留首张再选路追星；双核均二星参考 '+pct(advice.search.upgradePortfolio?.completionProbability??0)+'–'+pct(advice.search.optimisticUpgradeProbability??0)"><span>选路后关键二星</span><b>{{ pct(advice.search.keyUpgradePortfolio.completionProbability) }}–{{ pct(advice.search.optimisticKeyUpgradeProbability??advice.search.keyUpgradePortfolio.completionProbability) }}</b></div>
    <div class="search-goals"><div v-for="goal in advice.search.goals" :key="goal.id" class="search-goal" :title="goal.reason??'固定当前人口、金币和对手占牌；不是战斗胜率。'">
      <span><span v-for="target in goal.targets" :key="target.id" class="search-target"><img :src="dataset.characterById(target.id)?.image_path" :alt="name(target.id)"/><small>{{ target.copies===9?'三星':target.copies===3?'二星':'首张' }}</small></span></span>
      <b>{{ pct(goal.probability) }}–{{ pct(goal.optimisticProbability) }}</b><small>{{ goal.gold50===null?'预算内未达50%':'50%约 '+goal.gold50+' 金' }}</small>
    </div></div>
  </div>
  <small class="evidence" :title="advice.gaps.join('；')||'装备兼容、实际过渡关联与海克斯机制分别比较；选择阵容后才切换为指定阵容高亮。'">{{ advice.gaps.length?advice.gaps.join(' · '):'装备 · 过渡 · 海克斯' }}</small>
</section></template>
